async function api<T>(path: string, body?: unknown) {
  const r = await fetch(path, {
      method: body ? "POST" : "GET",
      cache: "no-store",
      headers: { "Content-Type": "application/json" },
      ...(body ? { body: JSON.stringify(body) } : {}),
    }),
    d = (await r.json()) as T & { message?: string };
