                  setMonth(e.target.value);
                  setOffset(0);
                }}
              />
            </label>
            {month && (
              <button
                onClick={() => {
                  setMonth("");
                  setOffset(0);
                }}
              >
                All months
              </button>
            )}
            <button disabled={busy || !list?.entries.length} onClick={digest}>
              <Icon name="download" />
              Export reports
            </button>
          </>
        )}
      </div>
      {tab === "report" && (
        <p className="ts-hint">
